	/// <summary>某分组可选值；分支随已选职业联动（未选职业时给出全部分支）。</summary>
	public static IReadOnlyList<string> OptionsOf(string key, IReadOnlyList<string>? pickedProf)
	{
		switch (key)
		{
			case "prof": return Professions;
			case "rar": return Rarities;
			case "pos": return Positions;
			case "sex": return Genders;
			case "obt": return Obtains;
			case "tag": return Tags;
			case "boxType": return Values(BoxTypes);
			case "sale": return Values(SaleTypes);
			case "rep": return Values(ReplicateTypes);
			case "sub":
			{
				var all = new List<string>();
				IEnumerable<string> keys = pickedProf is { Count: > 0 } ? pickedProf : SubProfessions.Keys;
				foreach (var p in keys)
				{
					if (!SubProfessions.TryGetValue(p, out var subs)) continue;
					foreach (var s in subs) if (!all.Contains(s)) all.Add(s);
				}
				return all;
			}
			default: return System.Array.Empty<string>();
		}
	}

	/// <summary>选项在界面上的显示文案（稀有度加星、盒类型翻译）。</summary>
	public static string LabelOf(string key, string value) => key switch
	{
		"rar" => value + "★",
		"boxType" => Lookup(BoxTypes, value),
		"sale" => Lookup(SaleTypes, value),
		"rep" => Lookup(ReplicateTypes, value),
		"year" => value + "年",
		_ => value,
	};

	private static string Lookup((string Value, string Label)[] table, string value)
	{
		foreach (var (v, label) in table) if (v == value) return label;
		return value;
	}

	private static string[] Values((string Value, string Label)[] table)
	{
		var result = new string[table.Length];
		for (var i = 0; i < table.Length; i++) result[i] = table[i].Value;
		return result;
	}
